const input = $json;

const headers = input.headers || input.header || {};
const body = input.body ?? null;

const signatureHeaderName = String(
  $env.FAILED_PAYMENT_SIGNATURE_HEADER_NAME || 'x-signature'
).toLowerCase();

let receivedSignature = null;

for (const [key, value] of Object.entries(headers)) {
  if (String(key).toLowerCase() === signatureHeaderName) {
    receivedSignature = Array.isArray(value) ? value[0] : value;
    break;
  }
}

const rawPayload =
  input.rawBody ??
  input.raw_body ??
  (typeof body === 'string' ? body : null);

return [
  {
    json: {
      ...input,
      failed_payment_webhook: {
        raw_payload: rawPayload,
        received_signature: receivedSignature,
        signature_header_name: signatureHeaderName,
        signature_present: Boolean(receivedSignature),
        raw_payload_present: rawPayload !== null && rawPayload !== undefined,
        extracted_at: new Date().toISOString()
      }
    }
  }
];

const crypto = require('crypto');

const webhook = $json.failed_payment_webhook || {};
const rawPayload = webhook.raw_payload;

if (rawPayload === null || rawPayload === undefined) {
  return [{
    json: {
      ...$json,
      failed_payment_webhook: {
        ...webhook,
        expected_signature: null,
        signature_computation_valid: false,
        signature_error: 'RAW_FAILED_PAYMENT_PAYLOAD_MISSING'
      }
    }
  }];
}

const secret = $env.FAILED_PAYMENT_WEBHOOK_HMAC_SECRET;

if (!secret) {
  throw new Error('FAILED_PAYMENT_WEBHOOK_HMAC_SECRET is not configured');
}

const payloadString = typeof rawPayload === 'string'
  ? rawPayload
  : JSON.stringify(rawPayload);

const expectedSignature = crypto
  .createHmac('sha256', secret)
  .update(payloadString, 'utf8')
  .digest('hex');

return [{
  json: {
    ...$json,
    failed_payment_webhook: {
      ...webhook,
      expected_signature: expectedSignature,
      signature_computation_valid: true,
      signature_computed_at: new Date().toISOString()
    }
  }
}];

const crypto = require('crypto');

const webhook = $json.failed_payment_webhook || {};
const received = String(webhook.received_signature || '').trim();
const expected = String(webhook.expected_signature || '').trim();

let signatureValid = false;
let comparisonPerformed = false;

if (received && expected && received.length === expected.length) {
  comparisonPerformed = true;
  signatureValid = crypto.timingSafeEqual(
    Buffer.from(received, 'utf8'),
    Buffer.from(expected, 'utf8')
  );
}

return [{
  json: {
    ...$json,
    failed_payment_webhook: {
      ...webhook,
      signature_comparison_performed: comparisonPerformed,
      signature_valid: signatureValid,
      signature_verification_status: signatureValid ? 'VALID' : 'INVALID',
      signature_verified_at: new Date().toISOString()
    }
  }
}];

const webhook = $json.failed_payment_webhook || {};

return [{
  json: {
    ...$json,
    security_alert: {
      event_type: 'FAILED_PAYMENT_WEBHOOK_SIGNATURE_INVALID',
      severity: 'HIGH',
      module: '2.9 Renewal/Dunning',
      plan_id: '3.0.3.4',
      message: 'Failed-payment webhook rejected because signature verification failed.',
      signature_present: Boolean(webhook.received_signature),
      comparison_performed: Boolean(webhook.signature_comparison_performed),
      verification_status: webhook.signature_verification_status || 'INVALID',
      occurred_at: new Date().toISOString()
    }
  }
}];

const webhook = $json.failed_payment_webhook || {};

if (webhook.signature_valid !== true) {
  throw new Error('SECURITY_GUARD_FAILED: Unverified failed-payment webhook attempted to enter dunning flow.');
}

return [{
  json: {
    ...$json,
    failed_payment_webhook: {
      ...webhook,
      security_status: 'VERIFIED',
      verified_for_dunning_processing: true,
      verified_for_dunning_processing_at: new Date().toISOString()
    }
  }
}];
